<span class="line"><span style="color:#ABB2BF;">    (</span><span style="color:#98C379;">&quot;帮我发邮件给 test@example.com&quot;</span><span style="color:#ABB2BF;">, </span><span style="color:#98C379;">&quot;邮箱应被脱敏&quot;</span><span style="color:#ABB2BF;">),</span></span>
