<span class="line"><span style="color:#ABB2BF;">        response </span><span style="color:#56B6C2;">=</span><span style="color:#C678DD;"> await</span><span style="color:#61AFEF;"> qa_func</span><span style="color:#ABB2BF;">(test_input)</span></span>
